import{_ as l,C as t,o as n,c as i,j as a,a as d,E as r,a2 as c}from"./chunks/framework.BBXLvvRa.js";const S=JSON.parse('{"title":"2026 机场订阅转换全流程实操与 Sub-Store 部署全攻略 (3000字深度实战)","description":"懂哥机独家教你安全实现机场节点订阅转换，从传统在线 Converter 避坑到自建 Sub-Store 脚本全流程，适配 Clash, Surge, Shadowrocket, Sing-Box。","frontmatter":{"title":"2026 机场订阅转换全流程实操与 Sub-Store 部署全攻略 (3000字深度实战)","description":"懂哥机独家教你安全实现机场节点订阅转换，从传统在线 Converter 避坑到自建 Sub-Store 脚本全流程，适配 Clash, Surge, Shadowrocket, Sing-Box。","category":"🛠️ 软件与教程中心","outline":[2,3],"aside":true},"headers":[],"relativePath":"tutorials/sub-converter.md","filePath":"tutorials/sub-converter.md"}'),p={name:"tutorials/sub-converter.md"};function g(u,e,h,b,m,v){const s=t("ArticleHeader"),o=t("ArticleLikes");return n(),i("div",null,[e[0]||(e[0]=a("h1",{id:"🛠️-2026-机场订阅转换全流程实操与-sub-store-部署全攻略-3000字深度实战",tabindex:"-1"},[d("🛠️ 2026 机场订阅转换全流程实操与 Sub-Store 部署全攻略 (3000字深度实战) "),a("a",{class:"header-anchor",href:"#🛠️-2026-机场订阅转换全流程实操与-sub-store-部署全攻略-3000字深度实战","aria-label":'Permalink to "🛠️ 2026 机场订阅转换全流程实操与 Sub-Store 部署全攻略 (3000字深度实战)"'},"​")],-1)),r(s,{likes:390,views:6100,badge:"深度干货",badgeClass:"badge-top",category:"🛠️ 软件与教程中心",date:"2026-08-17",id:"sub-converter",tags:"订阅转换, Sub-Store, Clash订阅, 节点脱敏, 隐私安全"}),e[1]||(e[1]=c(`<div class="intro-banner" style="background:var(--vp-c-bg-alt);border:1px solid var(--vp-c-gutter);border-left:4px solid #0284c7;padding:1.1rem 1.35rem;border-radius:8px;margin-bottom:1.8rem;font-size:0.95rem;line-height:1.7;color:var(--vp-c-text-2);"><strong>懂哥机导读：</strong>在使用不同平台（如 iOS 小火箭、Mac Surge、Windows Clash、Android Sing-Box）时，你是否常因机场给出的原始订阅格式不兼容而感到困扰？更危险的是，许多公开的免费“订阅转换网站”实际上在暗中偷偷收集用户的订阅 Token 甚至注入恶意广告节点！本深度指南将教你安全无痛地完成格式转换与节点去重。 </div><hr><h2 id="_1-引言与痛点分析" tabindex="-1">1. 引言与痛点分析 <a class="header-anchor" href="#_1-引言与痛点分析" aria-label="Permalink to &quot;1. 引言与痛点分析&quot;">​</a></h2><p>订阅转换是科学上网体系中极易被忽略的“安全盲区”：</p><ol><li><strong>公开第三方转换站的隐私泄露风险</strong>：公开转换服务通常需要将你的机场原始链接作为 URL 参数发送给其后端服务器。不怀好意的转换站运维人员可以通过日志抓取你的完整 Token，无偿套用你的流量，严重时直接导致账号由于“异地多 IP 异常并发”被机场冻结。</li><li><strong>格式不匹配导致内核报错</strong>：例如，将 VLESS + Reality 的高阶节点直接引入旧版 Clash 内核，或者将 Hysteria 2 订阅强行导入不支持 QUIC 的古早客户端，均会导致客户端报 <code>Unrecognized proxy type</code> 错误。</li><li><strong>多机场订阅融合管理难题</strong>：购买了多家备用机场的用户，往往需要在不同配置文件间频繁切换。</li></ol><hr><h2 id="_2-核心技术原理与架构" tabindex="-1">2. 核心技术原理与架构 <a class="header-anchor" href="#_2-核心技术原理与架构" aria-label="Permalink to &quot;2. 核心技术原理与架构&quot;">​</a></h2><p>订阅转换的本质是一个<strong>配置解析与模板渲染器</strong>（Parser &amp; Template Engine）。它将源格式（如 Base64 编码的 vmess:// 链接）解码为通用节点 JSON/YAML 字典，再通过规则映射模板（Rule-Template）重新渲染为目标客户端所需的格式。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> [机场原始订阅 (Base64/YAML)] </span></span>
<span class="line"><span>               │</span></span>
<span class="line"><span>               ▼</span></span>
<span class="line"><span>┌──────────────────────────────┐</span></span>
<span class="line"><span>│  解码器 (Base64 / ProtoBuf)  │</span></span>
<span class="line"><span>└──────────────┬───────────────┘</span></span>
<span class="line"><span>               │ (统一节点数据结构)</span></span>
<span class="line"><span>               ▼</span></span>
<span class="line"><span>┌──────────────────────────────┐</span></span>
<span class="line"><span>│ 模板引擎 (重命名/排序/筛选/分组)│</span></span>
<span class="line"><span>└──────────────┬───────────────┘</span></span>
<span class="line"><span>               │</span></span>
<span class="line"><span>               ▼</span></span>
<span class="line"><span> [目标客户端格式 (Clash/Surge/Sing-Box)]</span></span></code></pre></div><h3 id="几种订阅处理方式安全性对比表" tabindex="-1">几种订阅处理方式安全性对比表 <a class="header-anchor" href="#几种订阅处理方式安全性对比表" aria-label="Permalink to &quot;几种订阅处理方式安全性对比表&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">转换方式</th><th style="text-align:left;">隐私安全性</th><th style="text-align:left;">节点处理能力</th><th style="text-align:left;">运维门槛</th><th style="text-align:left;">适合人群</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>第三方公开转换站</strong></td><td style="text-align:left;">⚠️ 极低 (Token 易泄露)</td><td style="text-align:left;">基础</td><td style="text-align:left;">零门槛</td><td style="text-align:left;">仅限无敏感信息的临时试用节点</td></tr><tr><td style="text-align:left;"><strong>本地开源命令行/软件转换</strong></td><td style="text-align:left;">🛡️ 极高 (零数据上报)</td><td style="text-align:left;">中等</td><td style="text-align:left;">低</td><td style="text-align:left;">PC 端单机用户</td></tr><tr><td style="text-align:left;"><strong>自建 Sub-Store (Docker/Vercel)</strong></td><td style="text-align:left;">🛡️ 顶级 (私有化部署)</td><td style="text-align:left;">极强 (脚本/正则/自动化)</td><td style="text-align:left;">中等</td><td style="text-align:left;">拥有多设备与多机场的极客用户</td></tr></tbody></table><hr><h2 id="_3-保姆级实战操作手册" tabindex="-1">3. 保姆级实战操作手册 <a class="header-anchor" href="#_3-保姆级实战操作手册" aria-label="Permalink to &quot;3. 保姆级实战操作手册&quot;">​</a></h2><h3 id="方案-a-使用安全本地工具脱敏转换-零风险" tabindex="-1">方案 A: 使用安全本地工具脱敏转换 (零风险) <a class="header-anchor" href="#方案-a-使用安全本地工具脱敏转换-零风险" aria-label="Permalink to &quot;方案 A: 使用安全本地工具脱敏转换 (零风险)&quot;">​</a></h3><p>如果你不想搭建服务器，可使用 Clash Verge Rev 或 Stash 内置的本地转换能力：</p><ol><li>打开 Clash Verge Rev ➔ 进入 <strong>[订阅 (Profiles)]</strong> 面板。</li><li>点击右上角 <strong>[新建 (New)]</strong> ➔ 类型选择 <code>Import</code> ➔ 贴入机场原始链接。</li><li>在新建的订阅条目上点击右键 ➔ 选择 <strong>[编辑规则/预处理 (Merge Rules)]</strong>，在本地直接挂载自定义分组，无需任何网络中转。</li></ol><h3 id="方案-b-5分钟在-vercel-免费自建私有化-sub-store" tabindex="-1">方案 B: 5分钟在 Vercel 免费自建私有化 Sub-Store <a class="header-anchor" href="#方案-b-5分钟在-vercel-免费自建私有化-sub-store" aria-label="Permalink to &quot;方案 B: 5分钟在 Vercel 免费自建私有化 Sub-Store&quot;">​</a></h3><p>Sub-Store 是目前公认最强大的订阅管理工具。</p><ol><li><strong>Fork 仓库</strong>：在 GitHub 上搜索并 Fork <code>sub-store/sub-store</code> 仓库。</li><li><strong>部署到 Vercel</strong>：打开 Vercel 控制台 ➔ 点击 <strong>[New Project]</strong> ➔ 选择刚才 Fork 的仓库。</li><li><strong>设置访问密钥 (环境变量)</strong>： 在 Vercel 的 Environment Variables 中添加： <ul><li><code>SUB_STORE_SECRET</code>: <code>你的私密访问密码</code></li></ul></li><li><strong>部署完成</strong>：几秒后生成专属的 <code>https://your-app.vercel.app</code> 链接。</li><li><strong>添加订阅</strong>：打开 Sub-Store Web 界面 ➔ 点击右下角 <code>+</code> 号 ➔ 输入机场名称与原始链接 ➔ 勾选“节点去重”与“排序”，即可生成专属的安全订阅 URL。</li></ol><hr><h2 id="_4-进阶调试与极端场景处理" tabindex="-1">4. 进阶调试与极端场景处理 <a class="header-anchor" href="#_4-进阶调试与极端场景处理" aria-label="Permalink to &quot;4. 进阶调试与极端场景处理&quot;">​</a></h2><h3 id="场景-1-节点名称乱码或带有机场推广牛皮癣广告" tabindex="-1">场景 1: 节点名称乱码或带有机场推广牛皮癣广告 <a class="header-anchor" href="#场景-1-节点名称乱码或带有机场推广牛皮癣广告" aria-label="Permalink to &quot;场景 1: 节点名称乱码或带有机场推广牛皮癣广告&quot;">​</a></h3><ul><li><strong>解决方案</strong>：在 Sub-Store 或转换参数中加入正则替换规则： <ul><li>正则模式：<code>(?i)(官网|打折|群|客服|过期|剩余)</code> ➔ 替换为空。</li></ul></li></ul><h3 id="场景-2-hysteria-2-vless-节点转换后端口握手失败" tabindex="-1">场景 2: Hysteria 2 / VLESS 节点转换后端口握手失败 <a class="header-anchor" href="#场景-2-hysteria-2-vless-节点转换后端口握手失败" aria-label="Permalink to &quot;场景 2: Hysteria 2 / VLESS 节点转换后端口握手失败&quot;">​</a></h3><ul><li><strong>排错步骤</strong>：Hysteria 2 使用 UDP 传输，需确保转换参数中开启了 <code>udp: true</code>，且本地防火墙未拦截 UDP 端口。</li></ul><hr><h2 id="_5-懂哥机避坑与安全指南" tabindex="-1">5. 懂哥机避坑与安全指南 <a class="header-anchor" href="#_5-懂哥机避坑与安全指南" aria-label="Permalink to &quot;5. 懂哥机避坑与安全指南&quot;">​</a></h2><ol><li><strong>切勿在 Telegram 交流群直接发送你的订阅链接</strong>：哪怕带有一位字符的泄漏，都可能被自动化爬虫抓取。</li><li><strong>慎用免费在线 API</strong>：如果必须使用公共转换站，请手动将 URL 中的真实域名/Token 替换为占位符，转换后再在本地编辑器修改回来。</li></ol><hr><h2 id="_6-深度总结与-faq" tabindex="-1">6. 深度总结与 FAQ <a class="header-anchor" href="#_6-深度总结与-faq" aria-label="Permalink to &quot;6. 深度总结与 FAQ&quot;">​</a></h2><details class="faq-card" style="border:1px solid var(--vp-c-gutter);border-radius:8px;padding:0.85rem 1.2rem;margin-bottom:0.85rem;background:var(--vp-c-bg-alt);"><summary style="font-weight:800;cursor:pointer;color:var(--vp-c-text-1);">Q1: 为什么我的订阅转换后原本能解锁 Netflix 的节点失效了？</summary><div style="margin-top:0.65rem;font-size:0.9rem;color:var(--vp-c-text-2);line-height:1.65;"> 部分转化模板会在渲染时清空节点中的 \`udp: true\` 或 \`skip-cert-verify: true\` 标记，导致加密证书校验失败。建议在模板选项中勾选“保留原节点参数”。 </div></details><details class="faq-card" style="border:1px solid var(--vp-c-gutter);border-radius:8px;padding:0.85rem 1.2rem;margin-bottom:0.85rem;background:var(--vp-c-bg-alt);"><summary style="font-weight:800;cursor:pointer;color:var(--vp-c-text-1);">Q2: Sub-Store 如何实现自动定时同步机场更新？</summary><div style="margin-top:0.65rem;font-size:0.9rem;color:var(--vp-c-text-2);line-height:1.65;"> 在 Sub-Store 设置中开启 \`Cron\` 定时任务，或在 Vercel 中添加定时触发器，设置每 12 小时自动向上游机场同步一次最新 IP。 </div></details><details class="faq-card" style="border:1px solid var(--vp-c-gutter);border-radius:8px;padding:0.85rem 1.2rem;margin-bottom:0.85rem;background:var(--vp-c-bg-alt);"><summary style="font-weight:800;cursor:pointer;color:var(--vp-c-text-1);">Q3: 如何给转换后的节点加上国家国旗图标？</summary><div style="margin-top:0.65rem;font-size:0.9rem;color:var(--vp-c-text-2);line-height:1.65;"> 启用 Sub-Store 的脚本插件 \`Node Rename\`，内置国旗匹配正则会根据节点名称中的 &quot;HK/JP/US&quot; 自动前缀 🇭🇰 / 🇯🇵 / 🇺🇸 图标。 </div></details><details class="faq-card" style="border:1px solid var(--vp-c-gutter);border-radius:8px;padding:0.85rem 1.2rem;margin-bottom:0.85rem;background:var(--vp-c-bg-alt);"><summary style="font-weight:800;cursor:pointer;color:var(--vp-c-text-1);">Q4: 自建 Sub-Store 在 Vercel 上提示内存超限怎么办？</summary><div style="margin-top:0.65rem;font-size:0.9rem;color:var(--vp-c-text-2);line-height:1.65;"> 关闭不必要的日志记录功能，并精简同时托管的机场数量。 </div></details><details class="faq-card" style="border:1px solid var(--vp-c-gutter);border-radius:8px;padding:0.85rem 1.2rem;margin-bottom:0.85rem;background:var(--vp-c-bg-alt);"><summary style="font-weight:800;cursor:pointer;color:var(--vp-c-text-1);">Q5: 转换后的订阅能在 Clash 与 Sing-Box 之间无缝切换吗？</summary><div style="margin-top:0.65rem;font-size:0.9rem;color:var(--vp-c-text-2);line-height:1.65;"> 可以。只要 Sub-Store 的输出格式选择 \`Sing-Box\` 或 \`Clash\`，底层的节点数据源是一致的。 </div></details>`,35)),r(o,{initial:390,id:"sub-converter",mode:"bottom"})])}const f=l(p,[["render",g]]);export{S as __pageData,f as default};
